package dominoes

// Domino represents a single domino stone with two halves.
type Domino [2]int

// MakeChain attempts to order the given dominoes into a closed chain, where
// the dots on adjacent halves match and the first and last numbers match.
// It returns the chain and true on success, or nil and false if no chain
// exists.
func MakeChain(input []Domino) ([]Domino, bool) {
	if len(input) == 0 {
		return []Domino{}, true
	}
	if len(input) == 1 {
		if input[0][0] == input[0][1] {
			return []Domino{input[0]}, true
		}
		return nil, false
	}

	// A closed chain requires every value to appear an even number of times.
	degree := map[int]int{}
	for _, d := range input {
		degree[d[0]]++
		degree[d[1]]++
	}
	for _, v := range degree {
		if v%2 != 0 {
			return nil, false
		}
	}

	// Backtracking search: build the chain one stone at a time, trying each
	// remaining stone (in both orientations) that matches the open end.
	chain := make([]Domino, 0, len(input))
	remaining := make([]Domino, 0, len(input))

	var search func() bool
	search = func() bool {
		if len(remaining) == 0 {
			return chain[0][0] == chain[len(chain)-1][1]
		}
		end := chain[len(chain)-1][1]
		for i, d := range remaining {
			for _, next := range [2]Domino{{d[0], d[1]}, {d[1], d[0]}} {
				if next[0] != end {
					continue
				}
				chain = append(chain, next)
				remaining = append(remaining[:i], remaining[i+1:]...)
				if search() {
					return true
				}
				remaining = append(remaining, d)
				chain = chain[:len(chain)-1]
			}
		}
		return false
	}

	for i, d := range input {
		chain = []Domino{d}
		remaining = append(append([]Domino(nil), input[:i]...), input[i+1:]...)
		if search() {
			return chain, true
		}
	}

	return nil, false
}

